import{_ as n,C as r,o as a,c as l,j as t,a as i,b as h,w as s,E as p,a4 as d,a3 as c}from"./chunks/framework.DhF4LrUq.js";const w=JSON.parse('{"title":"Five-minute install","description":"The tester golden path - from an invitation email to a running build in under five minutes, entirely in the Tester Portal.","frontmatter":{"description":"The tester golden path - from an invitation email to a running build in under five minutes, entirely in the Tester Portal."},"headers":[],"relativePath":"get-started/five-minute-install.md","filePath":"get-started/five-minute-install.md"}'),u={name:"get-started/five-minute-install.md"};function g(m,e,f,b,v,A){const o=r("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t("h1",{id:"five-minute-install",tabindex:"-1"},[i("Five-minute install "),t("a",{class:"header-anchor",href:"#five-minute-install","aria-label":'Permalink to "Five-minute install"'},"​")],-1)),e[2]||(e[2]=t("p",null,"The tester golden path: from an invitation email to a running build in under five minutes, with no Console access and no help from anyone. This is the whole portal experience — if any step here feels slower than it should, that is a bug in our promise.",-1)),(a(),h(d,null,{default:s(()=>[p(o,{id:"mermaid-6",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20actor%20QA%20as%20Org%20admin%20%2F%20QA%0A%20%20%20%20participant%20SD%20as%20ShipperDog%0A%20%20%20%20participant%20T%20as%20Tester%20(phone)%0A%20%20%20%20participant%20P%20as%20Tester%20Portal%0A%0A%20%20%20%20QA-%3E%3ESD%3A%20Invite%20tester%20to%20the%20organization%0A%20%20%20%20SD--%3E%3ET%3A%20Invitation%20email%20with%20a%20one-time%20link%20(7-day%20TTL)%0A%20%20%20%20T-%3E%3EP%3A%20Open%20the%20link%0A%20%20%20%20P-%3E%3ESD%3A%20Accept%3A%20set%20a%20password%0A%20%20%20%20SD--%3E%3ET%3A%20Account%20active%2C%20tester%20record%20linked%0A%20%20%20%20T-%3E%3EP%3A%20Sign%20in%0A%20%20%20%20P-%3E%3ESD%3A%20List%20my%20applications%20(decision%20API)%0A%20%20%20%20SD--%3E%3EP%3A%20The%20authorized%20catalog%20(e.g.%20Banking)%0A%20%20%20%20T-%3E%3EP%3A%20Open%20the%20app%2C%20pick%20a%20version%0A%20%20%20%20P-%3E%3ESD%3A%20Authorized%20version%20history%20(builds%2C%20sizes%2C%20dates)%0A%20%20%20%20T-%3E%3EP%3A%20Download%20for%20my%20platform%0A%20%20%20%20SD-%3E%3ESD%3A%20Seven-layer%20DOWNLOAD%20decision%0A%20%20%20%20SD--%3E%3EP%3A%20Signed%20URL%20(minutes)%20%2B%20install%20guidance%20%2B%20telemetry%20token%0A%20%20%20%20P--%3E%3ET%3A%20Install%20the%20build%2C%20report%20issues%20from%20the%20app%0A%20%20%20%20T-%3E%3ESD%3A%20Feedback%20(bug%20%2F%20crash%20%2F%20...)%20with%20device%20context%0A%20%20%20%20SD--%3E%3ESD%3A%20Context%20attached%2C%20QA%20triages%2C%20metrics%20and%20gates%20read%20it%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=c('<h2 id="the-steps" tabindex="-1">The steps <a class="header-anchor" href="#the-steps" aria-label="Permalink to &quot;The steps&quot;">​</a></h2><h3 id="_1-accept-the-invite" tabindex="-1">1. Accept the invite <a class="header-anchor" href="#_1-accept-the-invite" aria-label="Permalink to &quot;1. Accept the invite&quot;">​</a></h3><p>Open the invitation link on your phone. You will be asked to set a password — that is the entire registration. The link is single-use and expires after seven days; ask for a fresh one if it has gone stale.</p><div class="tip custom-block"><p class="custom-block-title">No Console account needed</p><p>Testers are not organization members and never see the Console. Your access is your tenant membership plus the version grants an administrator configured — see <a href="/shipperdog/snapshot/concepts/authorization">authorization</a>.</p></div><h3 id="_2-sign-in-and-see-your-apps" tabindex="-1">2. Sign in and see your apps <a class="header-anchor" href="#_2-sign-in-and-see-your-apps" aria-label="Permalink to &quot;2. Sign in and see your apps&quot;">​</a></h3><p>Sign in at the portal address your team gave you. The home screen is <strong>My Applications</strong>: one card per application you are authorized to install, with its latest authorized version and per-platform availability. An honest empty catalog means you have no grants yet — contact your QA or tenant admin; it is never an error state.</p><h3 id="_3-pick-a-version" tabindex="-1">3. Pick a version <a class="header-anchor" href="#_3-pick-a-version" aria-label="Permalink to &quot;3. Pick a version&quot;">​</a></h3><p>Tap a card to see the app&#39;s version history — newest first, each with its status badge (draft, active, archived, revoked), the build number, size, and upload date. Every version is a shareable deep link, which is handy when reporting an issue against exactly one build.</p><h3 id="_4-install" tabindex="-1">4. Install <a class="header-anchor" href="#_4-install" aria-label="Permalink to &quot;4. Install&quot;">​</a></h3><p>Tap <strong>Download</strong> for your platform. The portal asks ShipperDog whether you may have this build; an allow returns a short-lived signed URL together with install guidance:</p><ul><li><strong>Android (direct)</strong> — you may be asked to allow installs from this source once; then the APK installs.</li><li><strong>iOS (direct)</strong> — works for ad-hoc or enterprise-signed builds with your device registered; most iOS testing flows through TestFlight instead, and the guidance will say so when that is the route.</li></ul><p>If the download dialog offers a <strong>telemetry token</strong>, the build you are installing embeds the ShipperDog SDK — nothing for you to do; install and crash context flows back automatically.</p><h3 id="_5-report-issues" tabindex="-1">5. Report issues <a class="header-anchor" href="#_5-report-issues" aria-label="Permalink to &quot;5. Report issues&quot;">​</a></h3><p><strong>Report issue</strong> on any version opens the feedback form: pick a type (bug, feedback, crash, feature request, UX issue, security issue), describe it, optionally attach screenshots, videos, or logs. The platform attaches the context for you — app, version, build, device, OS — so &quot;which build were you on?&quot; is a question nobody has to ask.</p><p>That is the whole loop. QA triages your reports; critical ones gate promotions; your installs and sessions feed the metrics that decide how wide the release spreads.</p><h2 id="step-by-step-guides" tabindex="-1">Step-by-step guides <a class="header-anchor" href="#step-by-step-guides" aria-label="Permalink to &quot;Step-by-step guides&quot;">​</a></h2><p>Each part of the path above has its own short guide in the how-to section:</p><ol><li><a href="/shipperdog/snapshot/how-to/portal/accept-invite">Accept an invitation</a></li><li><a href="/shipperdog/snapshot/how-to/portal/browse-apps">Browse your applications</a> — the catalog and the version history</li><li><a href="/shipperdog/snapshot/how-to/portal/install-android">Install on Android</a> / <a href="/shipperdog/snapshot/how-to/portal/install-ios">install on iOS</a></li><li><a href="/shipperdog/snapshot/how-to/portal/feedback">Submit feedback</a></li></ol><h2 id="for-administrators-what-makes-this-work" tabindex="-1">For administrators: what makes this work <a class="header-anchor" href="#for-administrators-what-makes-this-work" aria-label="Permalink to &quot;For administrators: what makes this work&quot;">​</a></h2><p>The five-minute promise rests on four setup facts, all covered elsewhere in these docs:</p><ol><li>The tester is invited and linked to a tenant (<a href="/shipperdog/snapshot/concepts/tenancy-isolation">tenancy</a>).</li><li>The tester holds a version grant — explicit, application-wide, by tag, or latest-N (<a href="/shipperdog/snapshot/concepts/authorization">authorization</a>).</li><li>A release targets the tester&#39;s tenant and has reached a ring whose eligibility admits it (<a href="/shipperdog/snapshot/concepts/rings-and-rollout">rings</a>).</li><li>The artifact passed validation (<a href="/shipperdog/snapshot/concepts/artifact-pipeline">artifact pipeline</a>).</li></ol><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/shipperdog/snapshot/get-started/concepts">Core concepts</a> — the nouns behind the screens you just used</li><li><a href="/shipperdog/snapshot/get-started/platform-tour">Platform tour</a> — what your administrators see on the other side</li></ul>',23))])}const k=n(u,[["render",g]]);export{w as __pageData,k as default};
